INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6e35250f-3494-46c4-8a9e-16fd80ebbf64', 'c3c3c3c3-3030-4000-8000-000000000003', 10, 'Dia 10 — Foco', 'Semana 2: Organizar', '{"pch": "Olhando para Jesus\u2026 autor e consumador da f\u00e9. Foco \u00e9 decidir para onde olhar.", "verse": "Hb 12,2", "lectio": "Leia Hb 12,1-3. Correr com perseveran\u00e7a.", "practice": "Escolha 1 coisa importante. Dedique 1 hora ininterrupta a ela.", "question": "No que voc\u00ea deveria estar focado mas n\u00e3o est\u00e1?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;